.sidebar {
  background: var(--color-bg-tertiary);
  border-right: 1px solid var(--color-border-medium);
  padding: 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  height: 100vh;
}

.sidebar--collapsed {
  border-right: 1px solid var(--color-border-medium);
  width: 44px;
  min-width: 44px;
}

.sidebar__top {
  flex-shrink: 0;
  background: var(--color-bg-tertiary);
  border-bottom: 1px solid var(--color-border-medium);
  position: sticky;
  top: 0;
  z-index: 1;
}

.sidebar__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
}

.sidebar--collapsed .sidebar__top {
  border-bottom: none;
}

.sidebar--collapsed .sidebar__header {
  justify-content: center;
  padding: 12px 8px;
}

.sidebar__actions {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 0 0 8px;
}

.sidebar__action-btn {
  background: none;
  border: 1px solid var(--color-border-medium);
  cursor: pointer;
  width: 30px;
  height: 30px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 6px;
  color: var(--color-text-muted);
  transition: background 0.15s, color 0.15s;
}

.sidebar__action-btn:hover {
  background: var(--color-bg-hover-strong);
  color: var(--color-text-primary);
}

.sidebar__action-btn:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.sidebar__action-btn--danger:hover:not(:disabled) {
  background: var(--color-error-bg-subtle);
  color: var(--color-error);
}

.sidebar__title {
  margin: 0;
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--color-text-muted);
}

.sidebar--collapsed .sidebar__title {
  display: none;
}

.sidebar__content {
  flex: 1 1 0;
  min-height: 0;
  overflow-y: auto;
  padding: 12px 16px;
}

.sidebar--collapsed .sidebar__content {
  display: none;
}

.sidebar__conversations {
  flex: 1.5;
  min-height: 0;
  border-top: 1px solid var(--color-border-medium);
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.sidebar--collapsed .sidebar__conversations {
  display: none;
}

.sidebar__collapse-toggle {
  background: none;
  border: none;
  cursor: pointer;
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 4px;
  flex-shrink: 0;
}

.sidebar__collapse-toggle:hover {
  background: var(--color-bg-hover-strong);
}

.sidebar__hamburger {
  display: block;
  width: 16px;
  height: 2px;
  background: var(--color-text-muted);
  position: relative;
}

.sidebar__hamburger::before,
.sidebar__hamburger::after {
  content: '';
  display: block;
  width: 16px;
  height: 2px;
  background: var(--color-text-muted);
  position: absolute;
  left: 0;
}

.sidebar__hamburger::before {
  top: -5px;
}

.sidebar__hamburger::after {
  top: 5px;
}

.sidebar__empty {
  font-size: 13px;
  color: var(--color-text-faint);
}

.sidebar__list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.sidebar__item {
  margin-bottom: 4px;
}

.sidebar__table-header {
  display: flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
}

.sidebar__toggle {
  background: none;
  border: none;
  cursor: pointer;
  font-size: 10px;
  padding: 2px 4px;
  color: var(--color-text-muted);
