.sidebar__col-name {
  color: var(--color-text-primary);
}

.sidebar__col-type {
  color: var(--color-text-faint);
  font-style: italic;
}

.sidebar__footer {
  flex-shrink: 0;
  border-top: 1px solid var(--color-border-medium);
  padding: 8px 16px;
  display: flex;
  align-items: center;
}

.sidebar--collapsed .sidebar__footer {
  justify-content: center;
